use vstd::prelude::*;

verus! {

    fn check_below_threshold(l: Vec<i8>, t: i8) -> (result: bool)
        ensures
            // The result exactly says “for all valid indices i, l@[i] < t”
            result == forall |i: usize| i < l.len() ==> l@[i] < t,
    {
        let mut i: usize = 0;
        // iterate over the vector
        while i < l.len()
            invariant
                // i stays between 0 and l.len()
                0 <= i && i <= l.len(),
                // all elements before i are below t
                forall |j: usize| j < i ==> l@[j] < t,
            decreases l.len() - i,
        {
            // connect the runtime indexing l[i] with the spec‐level l@[i]
            assert(l[i] == l@[i]);
            // if we ever find l[i] >= t, we can return false
            if !(l[i] < t) {
                return false;
            }
            i += 1;
        }
        // no counterexample found ⇒ true
        true
    }

}

fn main() {
    // some quick smoke tests
    let v1 = Vec::from_slice(&[ -5i8, 0, 3 ]);
    assert!(check_below_threshold(v1.clone(), 4));   // all below 4
    assert!(!check_below_threshold(v1.clone(), 0));  // -5<0, but 0≱0 fails strictly-less
    assert!(check_below_threshold(Vec::new(), 0));   // empty ⇒ true
}